"""SCF manager: parsing, backup/restore, and regex-based queries.

# pyright: reportMissingTypeStubs=false
"""

import time
import re
from lxml import etree  # type: ignore[reportMissingTypeStubs]
from typing import TYPE_CHECKING, Optional, List
from taf.ul.sbts.energy_saving.decorators.connection import with_connection
from taf.ul.sbts.energy_saving.exceptions import SCFError


if TYPE_CHECKING:
    from taf.ul.sbts.energy_saving.core.context import EnergySavingContext


class SCFManager:
    """SCF file management"""

    def __init__(self, context: 'EnergySavingContext'):
        self.context = context

    @with_connection
    def backup_scf(self, file_name: Optional[str] = None, save_path: str = "/tmp/",
                   timeout: int = 60, connection=None) -> str:
        """Backup current SCF file"""
        if file_name is None:
            timestamp = time.strftime("%Y%m%d_%H%M%S")
            alias_value = self.context.connection_alias or "noalias"
            alias_safe = alias_value.replace(':', '_').replace('/', '_')
            file_name = f"scf_backup_{alias_safe}_{timestamp}.xml"

        return self.context.admin.get_current_scf_file(save_path, file_name, timeout=timeout, connection=connection)

    @with_connection
    def get_string_scf(self, timeout: int = 60, connection=None) -> str:
        return self.context.admin.get_scf(timeout=timeout, connection=connection)

    @with_connection
    def restore_scf(self, scf_file_path: str, bts_id: Optional[int] = None, timeout: int = 600, connection=None):
        """Restore SCF from file"""
        return self.context.admin.perform_commissioning(
            scf_file=scf_file_path, connection=connection, bts_id=bts_id, timeout=timeout
        )

    @staticmethod
    def load_scf_xml(scf_file_path: str):
        """Load SCF from XML file to etree object"""
        try:
            tree = etree.parse(scf_file_path)
            return tree.getroot()
        except (etree.ParseError, IOError):
            try:
                with open(scf_file_path, 'r', encoding='utf-8') as f:
                    xml_content = f.read()
                return etree.XML(xml_content.encode())
            except Exception as ex:
                raise SCFError(f"Failed to load SCF file: {scf_file_path}") from ex

    @staticmethod
    def get_managed_object_by_dist_name(xml_scf, dist_name: str):
        """Get managed object by distName from XML SCF"""
        try:
            ns = {'ns': xml_scf.nsmap[None]} if xml_scf.nsmap[None] else {}
            if ns:
                return xml_scf.find(f".//ns:managedObject[@distName='{dist_name}']", namespaces=ns)
            else:
                return xml_scf.find(f".//managedObject[@distName='{dist_name}']")
        except Exception as e:
            raise SCFError(f"Failed to find managed object {dist_name}") from e

    @staticmethod
    def get_params_from_managed_object(xml_scf, dist_name: str, include_lists: bool = True):    # noqa: C901
        """
        Get parameters (p + list recursively) from a managedObject by distName.
        list representation:
          - 0 items  -> {}
          - 1 item   -> dict
          - >1 items -> list[dict]
        """
        try:
            element = SCFManager.get_managed_object_by_dist_name(xml_scf, dist_name)
            if element is None:
                return None

            def strip_tag(tag: str) -> str:
                return tag.split('}', 1)[1] if '}' in tag else tag

            def parse_children(parent) -> dict:
                out: dict = {}
                for child in parent:
                    tag = strip_tag(child.tag)
                    if tag == 'p':
                        name = child.get('name')
                        if name:
                            out[name] = (child.text.strip() if child.text else "")
                    elif include_lists and tag == 'list':
                        list_name = child.get('name')
                        if not list_name:
                            continue
                        items = [
                            parse_children(it)
                            for it in child
                            if strip_tag(it.tag) == 'item'
                        ]
                        if not items:
                            out[list_name] = {}
                        elif len(items) == 1:
                            out[list_name] = items[0]
                        else:
                            out[list_name] = items
                return out

            return parse_children(element)
        except Exception as e:
            raise SCFError(f"Failed to get parameters from {dist_name}") from e

    @staticmethod
    def scf_to_string(xml_scf) -> str:
        """Convert XML SCF to string."""
        return etree.tostring(xml_scf, encoding='unicode', pretty_print=True)

    @staticmethod
    def string_to_xml_scf(xml_content: str):
        """Convert SCF XML string back to etree root element."""
        try:
            # lxml.etree.fromstring wymaga bytes; string enkodujemy do UTF-8
            return etree.fromstring(xml_content.encode("utf-8"))
        except etree.XMLSyntaxError as ex:
            raise SCFError("Failed to parse SCF XML string") from ex

    @staticmethod
    def find_objects_with_groups(
        scf_xml_or_string, pattern: str, group_index: int = 0
    ) -> List[str]:
        """
        Find objects using regex pattern and return specific group.
        Do not inject user's pattern (with possible '$') into the attribute-search regex;
        anchors should apply to the distName substring, not the surrounding pattern.
        """
        string_scf = (
            scf_xml_or_string
            if isinstance(scf_xml_or_string, str)
            else SCFManager.scf_to_string(scf_xml_or_string)
        )

        dist_name_regex = re.compile(r'distName="([^"]+)"')
        matches: List[str] = []
        for match in dist_name_regex.finditer(string_scf):
            full_distname = match.group(1)
            object_match = re.search(pattern, full_distname)
            if not object_match:
                continue
            try:
                if group_index == 0:
                    matches.append(object_match.group(0))
                else:
                    matches.append(object_match.group(group_index))
            except IndexError:
                continue
        return matches

    def get_ids_by_pattern(self, scf_xml_or_string, pattern: str) -> List[int]:
        """Get integer IDs captured by a regex with a single group."""
        id_strings = self.find_objects_with_groups(
            scf_xml_or_string, pattern, group_index=1
        )
        return sorted({int(id_str) for id_str in id_strings})

    def get_distnames_by_pattern(self, scf_xml_or_string, pattern: str) -> List[str]:
        """Get distNames using a regex pattern."""
        return self.find_objects_with_groups(
            scf_xml_or_string, pattern, group_index=0
        )

    @staticmethod
    def get_nrbts_distnames(scf_xml_or_string) -> List[str]:
        """Get NRBTS distNames - returns full distName strings."""
        return SCFManager.find_objects_with_groups(
            scf_xml_or_string, r"(MRBTS-\d+/NRBTS-\d+)$", group_index=0
        )

    @staticmethod
    def get_lnbts_distnames(scf_xml_or_string) -> List[str]:
        """Get LNBTS distNames - returns full distName strings."""
        return SCFManager.find_objects_with_groups(
            scf_xml_or_string, r"(MRBTS-\d+/LNBTS-\d+)$", group_index=0
        )

    def __repr__(self):
        return f"SCFManager(context={self.context.connection_alias})"
